const cfg = $('Config').first().json;
const items = $input.all().map((i) => i.json);
let rows = [];
if (items.length === 1 && Array.isArray(items[0])) rows = items[0];
else if (items.length === 1 && Array.isArray(items[0]?.data)) rows = items[0].data;
else rows = items.filter((r) => r && r.product_id);

const ids = [...new Set(rows.map((r) => r.product_id).filter(Boolean))];
if (!ids.length) {
  return [{ json: { ...cfg, skip: true, motivo: 'lista_compra_vazia', lista_count: 0 } }];
}
return [{ json: { ...cfg, skip: false, ids_csv: ids.join(','), lista_count: ids.length } }];

const cfg = $('Config').first().json;
const maxDetalhe = Number(cfg.detalhe_max ?? 120);
const items = $input.all().map((i) => i.json);
let list = [];
if (items.length === 1 && Array.isArray(items[0])) list = items[0];
else if (items.length === 1 && Array.isArray(items[0]?.data)) list = items[0].data;
else list = items.filter((r) => r && r.id);

const pendentes = [];
let jaTem = 0;
let semExternal = 0;
for (const p of list) {
  // Sempre detalha se falta supplier OU se multiple ainda é 1 (para puxar caixa do BLING)
  const needsSupplier = !p.supplier_id;
  const needsMultiple = !(Number(p.purchase_multiple) > 1);
  if (!needsSupplier && !needsMultiple) { jaTem += 1; continue; }
  if (!p.external_id) { semExternal += 1; continue; }
  if (pendentes.length >= maxDetalhe) break;
  pendentes.push({
    product_uuid: p.id,
    bling_id: String(p.external_id),
    name: p.name,
    current_supplier_id: p.supplier_id || null,
    current_multiple: Number(p.purchase_multiple) > 0 ? Number(p.purchase_multiple) : 1,
  });
}

return [{
  json: {
    ...cfg,
    skip_detalhe: pendentes.length === 0,
    ja_vinculados: jaTem,
    pendentes: pendentes.length,
    produtos_lidos: list.length,
    sem_external_id: semExternal,
    lista_count: $('Prep IDs').first().json.lista_count ?? 0,
    fila: pendentes,
  },
}];

const filaMeta = $('Fila detalhe').first().json;
const cfg = $('Config').first().json;
return (filaMeta.fila || []).map((p) => ({
  json: {
    product_uuid: p.product_uuid,
    bling_id: p.bling_id,
    name: p.name,
    current_supplier_id: p.current_supplier_id,
    current_multiple: p.current_multiple,
    bling_base_url: cfg.bling_base_url,
    supabase_url: cfg.supabase_url,
  },
}));

const cfg = $('Config').first().json;
const filaMeta = $('Fila detalhe').first().json;
const expand = $('Expand fila').all();
const detalhes = $('BLING - Detalhe').all();

function extractMultiple(data) {
  const candidates = [
    data?.itensPorCaixa,
    data?.itens_por_caixa,
    data?.quantidadeItensPorCaixa,
    data?.estoque?.itensPorCaixa,
    data?.dimensoes?.itensPorCaixa,
    data?.tributacao?.itensPorCaixa,
  ];
  for (const v of candidates) {
    const n = Number(v);
    if (Number.isFinite(n) && n > 1) return Math.round(n);
  }
  return null;
}

function digitsOnly(value) {
  if (value === undefined || value === null) return null;
  const digits = String(value).replace(/\D/g, '');
  return digits.length > 0 ? digits : null;
}

function extractDocument(contato) {
  return digitsOnly(
    contato?.numeroDocumento ?? contato?.cpfCnpj ?? contato?.documento ?? contato?.cnpj ?? contato?.cpf ?? null
  );
}

/** Prioridade: gtin → gtinEmbalagem. Trim; ignora vazio / SEM GTIN. */
function extractGtin(data) {
  const candidates = [data?.gtin, data?.gtinEmbalagem, data?.tributacao?.gtin, data?.tributacao?.gtinEmbalagem];
  for (const raw of candidates) {
    if (raw === undefined || raw === null) continue;
    const s = String(raw).trim();
    if (!s) continue;
    if (/^sem\s*gtin$/i.test(s)) continue;
    return s;
  }
  return null;
}

const supplierByExt = new Map();
const links = [];
const multiplePatches = [];
const gtinPatches = [];
let erros = 0;
let semForn = 0;
let semGtin = 0;
let exemplo = null;
let exemploFid = null;
let exemploMultiple = null;
let exemploGtin = null;
let multiplesFound = 0;

for (let i = 0; i < detalhes.length; i++) {
  const d = detalhes[i];
  const meta = expand[i]?.json;
  if (!meta?.product_uuid) continue;

  const body = d.json;
  if (body?.error || (body?.status && body.status >= 400)) {
    erros += 1;
    continue;
  }
  const data = body.data ?? body;
  if (!data || typeof data !== 'object' || data.error) {
    erros += 1;
    continue;
  }

  const forn = data.fornecedor;
  const contato = forn?.contato;
  const fid = contato?.id != null ? String(contato.id) : null;
  const nome = String(contato?.nome || '').trim() || (fid ? ('Contato ' + fid) : null);

  if (!exemplo && forn) {
    exemplo = JSON.stringify(forn).slice(0, 280);
    exemploFid = fid;
  }

  const blingMult = extractMultiple(data);
  if (blingMult && !exemploMultiple) exemploMultiple = blingMult;
  if (blingMult && Number(meta.current_multiple) <= 1) {
    multiplesFound += 1;
    multiplePatches.push({
      product_uuid: meta.product_uuid,
      purchase_multiple: blingMult,
    });
  }

  // PATCH 011.1: GTIN só quando o detalhe já foi consultado pela fila (supplier/multiple)
  const gtin = extractGtin(data);
  if (gtin) {
    if (!exemploGtin) exemploGtin = gtin;
    gtinPatches.push({ product_uuid: meta.product_uuid, gtin });
  } else {
    semGtin += 1;
  }

  // Só vincula fornecedor se ainda não tiver
  if (!meta.current_supplier_id) {
    if (!fid) { semForn += 1; }
    else {
      const row = {
        company_id: cfg.company_id,
        external_id: fid,
        name: nome,
      };
      const document = extractDocument(contato);
      if (document) row.document = document;
      supplierByExt.set(fid, row);
      links.push({ product_uuid: meta.product_uuid, external_id: fid, nome });
    }
  }
}

const suppliers = [...supplierByExt.values()];
const chunks = [];
for (let i = 0; i < suppliers.length; i += 50) chunks.push(suppliers.slice(i, i + 50));

return [{
  json: {
    // false se houver qualquer trabalho (forn / multiple / gtin) — senão Resultado pula Montar patches
    skip_upsert: suppliers.length === 0 && multiplePatches.length === 0 && gtinPatches.length === 0,
    only_multiples: suppliers.length === 0 && multiplePatches.length > 0 && gtinPatches.length === 0,
    supabase_url: cfg.supabase_url,
    chunks,
    links,
    multiplePatches,
    gtinPatches,
    suppliers_to_upsert: suppliers.length,
    multiples_to_patch: multiplePatches.length,
    gtins_to_patch: gtinPatches.length,
    vinculados_previstos: links.length,
    sem_fornecedor: semForn,
    sem_gtin: semGtin,
    erros,
    exemplo_fornecedor: exemplo,
    exemplo_fid: exemploFid,
    exemplo_multiple: exemploMultiple,
    exemplo_gtin: exemploGtin,
    lista_count: filaMeta.lista_count ?? 0,
    pendentes: filaMeta.pendentes ?? 0,
    ja_vinculados: filaMeta.ja_vinculados ?? 0,
  },
}];

const row = $('Coletar contatos').first().json;
if (!row.chunks?.length) {
  // Sem fornecedores novos — segue para Montar patches (múltiplos)
  return [{ json: { skip_http: true, supabase_url: row.supabase_url, body: [] } }];
}
return row.chunks.map((body) => ({
  json: { body, supabase_url: row.supabase_url, skip_http: false },
}));

const cfg = $('Config').first().json;
const coletar = $('Coletar contatos').first().json;

const upserted = [];
try {
  for (const it of $('Supabase - Upsert forn').all()) {
    const j = it.json;
    if (Array.isArray(j)) upserted.push(...j);
    else if (Array.isArray(j?.data)) upserted.push(...j.data);
    else if (j && j.id && j.external_id) upserted.push(j);
  }
} catch (e) {}

const map = new Map();
for (const s of upserted) {
  if (s?.external_id != null && s?.id) map.set(String(s.external_id), s.id);
}

const patches = [];
let semMatch = 0;
for (const link of coletar.links || []) {
  const sid = map.get(String(link.external_id));
  if (!sid) { semMatch += 1; continue; }
  patches.push({
    json: {
      url: cfg.supabase_url + '/rest/v1/products?id=eq.' + link.product_uuid,
      body: { supplier_id: sid },
      skip_patch: false,
    },
  });
}

for (const m of coletar.multiplePatches || []) {
  patches.push({
    json: {
      url: cfg.supabase_url + '/rest/v1/products?id=eq.' + m.product_uuid,
      body: { purchase_multiple: m.purchase_multiple },
      skip_patch: false,
    },
  });
}

// PATCH 011.1: só envia gtin quando extraiu valor válido (nunca null / nunca apaga)
for (const g of coletar.gtinPatches || []) {
  patches.push({
    json: {
      url: cfg.supabase_url + '/rest/v1/products?id=eq.' + g.product_uuid,
      body: { gtin: g.gtin },
      skip_patch: false,
    },
  });
}

const base = {
  vinculados: (coletar.links || []).length - semMatch,
  multiples_patched: (coletar.multiplePatches || []).length,
  gtins_patched: (coletar.gtinPatches || []).length,
  sem_fornecedor: coletar.sem_fornecedor ?? 0,
  sem_gtin: coletar.sem_gtin ?? 0,
  sem_match: semMatch,
  erros: coletar.erros ?? 0,
  exemplo_fornecedor: coletar.exemplo_fornecedor ?? null,
  exemplo_fid: coletar.exemplo_fid ?? null,
  exemplo_multiple: coletar.exemplo_multiple ?? null,
  exemplo_gtin: coletar.exemplo_gtin ?? null,
  map_has_exemplo: coletar.exemplo_fid ? map.has(String(coletar.exemplo_fid)) : null,
  fornecedores_upserted: map.size,
  suppliers_to_upsert: coletar.suppliers_to_upsert ?? 0,
  lista_count: coletar.lista_count ?? 0,
  pendentes: coletar.pendentes ?? 0,
  ja_vinculados: coletar.ja_vinculados ?? 0,
  sample_external_ids: [...map.keys()].slice(0, 3),
  upsert_sample: upserted[0] ? JSON.stringify(upserted[0]).slice(0, 200) : null,
};

if (!patches.length) return [{ json: { skip_patch: true, ...base, vinculados: 0 } }];
return patches.map((p, idx) => ({
  json: {
    ...p.json,
    ...base,
    exemplo_fornecedor: idx === 0 ? base.exemplo_fornecedor : null,
    sample_external_ids: idx === 0 ? base.sample_external_ids : null,
    upsert_sample: idx === 0 ? base.upsert_sample : null,
  },
}));

const prep = $('Prep IDs').first().json;
let out = {
  status: 'ok',
  lista_count: prep.lista_count ?? 0,
  vinculados: 0,
  multiples_patched: 0,
  gtins_patched: 0,
  sem_fornecedor: 0,
  sem_gtin: 0,
  sem_match: 0,
  erros: 0,
  exemplo_fornecedor: null,
  exemplo_fid: null,
  exemplo_multiple: null,
  exemplo_gtin: null,
  map_has_exemplo: null,
  fornecedores_upserted: 0,
  suppliers_to_upsert: 0,
  ja_vinculados: 0,
  pendentes: 0,
  produtos_lidos: 0,
  sample_external_ids: null,
  upsert_sample: null,
};

if (prep.skip) {
  return [{ json: { ...out, motivo: prep.motivo } }];
}

try {
  const f = $('Fila detalhe').first().json;
  out.ja_vinculados = f.ja_vinculados ?? 0;
  out.pendentes = f.pendentes ?? 0;
  out.produtos_lidos = f.produtos_lidos ?? 0;
  if (f.skip_detalhe) {
    return [{ json: { ...out, motivo: out.ja_vinculados > 0 ? 'ja_todos_vinculados' : 'fila_vazia' } }];
  }
} catch (e) {}

try {
  const c = $('Coletar contatos').first().json;
  out.sem_fornecedor = c.sem_fornecedor ?? 0;
  out.sem_gtin = c.sem_gtin ?? 0;
  out.erros = c.erros ?? 0;
  out.exemplo_fornecedor = c.exemplo_fornecedor ?? null;
  out.exemplo_fid = c.exemplo_fid ?? null;
  out.exemplo_multiple = c.exemplo_multiple ?? null;
  out.exemplo_gtin = c.exemplo_gtin ?? null;
  out.suppliers_to_upsert = c.suppliers_to_upsert ?? 0;
  if (c.skip_upsert) {
    return [{ json: { ...out, motivo: 'sem_contatos_no_detalhe' } }];
  }
} catch (e) {}

try {
  const p = $('Montar patches').first().json;
  out = {
    ...out,
    vinculados: p.vinculados ?? 0,
    multiples_patched: p.multiples_patched ?? 0,
    gtins_patched: p.gtins_patched ?? 0,
    sem_match: p.sem_match ?? 0,
    sem_gtin: p.sem_gtin ?? out.sem_gtin,
    map_has_exemplo: p.map_has_exemplo ?? null,
    fornecedores_upserted: p.fornecedores_upserted ?? 0,
    sample_external_ids: p.sample_external_ids ?? null,
    upsert_sample: p.upsert_sample ?? null,
    exemplo_fornecedor: p.exemplo_fornecedor ?? out.exemplo_fornecedor,
    exemplo_fid: p.exemplo_fid ?? out.exemplo_fid,
    exemplo_multiple: p.exemplo_multiple ?? out.exemplo_multiple,
    exemplo_gtin: p.exemplo_gtin ?? out.exemplo_gtin,
  };
} catch (e) {}

return [{ json: out }];
